  const [genUnscheduled, setGenUnscheduled] = useState<Array<{ subject: string; hours: number }>>([]);
  const [genError, setGenError] = useState("");
  const [genSuccess, setGenSuccess] = useState("");
  const [genLoading, setGenLoading] = useState(false);
  const [initializedCollegeId, setInitializedCollegeId] = useState("");
  const [viewerClassGroup, setViewerClassGroup] = useState("");
  const [viewerShift, setViewerShift] = useState<"shift_1" | "shift_2" | "general">("general");

  // Quick Add Subject states in Generator
  const [showQuickAddForm, setShowQuickAddForm] = useState(false);
  const [quickSubName, setQuickSubName] = useState("");
  const [quickSubHours, setQuickSubHours] = useState(4);
  const [quickSubRoom, setQuickSubRoom] = useState("");
  const [quickSubMentorId, setQuickSubMentorId] = useState("");
  const [quickSubType, setQuickSubType] = useState("theory");

  // 5. Academic Monitoring states
  const [studentSearch, setStudentSearch] = useState("");
  const deferredStudentSearch = useDeferredValue(studentSearch);
  const [studentDeptFilter, setStudentDeptFilter] = useState("all");
  const [studentBatchFilter, setStudentBatchFilter] = useState("all");
  const [studentAttendanceFilter, setStudentAttendanceFilter] = useState("all");
  const [attendancePage, setAttendancePage] = useState(1);
  const [attendancePageSize, setAttendancePageSize] = useState(50);
  const [selectedHeaderDateModal, setSelectedHeaderDateModal] = useState<string | null>(null);
  const [dateModalSearch, setDateModalSearch] = useState("");
  const [dateModalStatusFilter, setDateModalStatusFilter] = useState<"all" | "present" | "absent" | "od" | "unmarked">("all");
  const [dateModalDeptFilter, setDateModalDeptFilter] = useState("all");
  const [dateModalCohortFilter, setDateModalCohortFilter] = useState("all");

  // 6. Tasks & Issues states
  const localTasks = localTasksFromDB;
  const issues = localIssuesFromDB;
  const [issueTitle, setIssueTitle] = useState("");
  const [issueType, setIssueType] = useState("academic");
  const [issuePriority, setIssuePriority] = useState("high");
  const [issueDesc, setIssueDesc] = useState("");
  const [editingIssueId, setEditingIssueId] = useState<string | null>(null);

  // Inline Issue Edit states
  const [editIssueTitle, setEditIssueTitle] = useState("");
  const [editIssueDesc, setEditIssueDesc] = useState("");
  const [editIssueType, setEditIssueType] = useState("academic");
  const [editIssuePriority, setEditIssuePriority] = useState("high");

  // Issues Filters
  const [issueStatusFilter, setIssueStatusFilter] = useState("all");
  const [issueTypeFilter, setIssueTypeFilter] = useState("all");
  const [issueSearchQuery, setIssueSearchQuery] = useState("");
  const [allowedProfileEditClasses, setAllowedProfileEditClasses] = useState<string[]>([]);

  // Handover Review States
  const [reviewingRequestId, setReviewingRequestId] = useState<string | null>(null);
  const [reviewReason, setReviewReason] = useState("");
  const [handoverSubject, setHandoverSubject] = useState<string>("original");
  const [selectedSubjName, setSelectedSubjName] = useState<string>("");
  const [customSubjName, setCustomSubjName] = useState<string>("");

  // CAM Direct Cover Allocation Modal states
  const [camAssigningReq, setCamAssigningReq] = useState<any | null>(null);
  const [camAssignAvailableMentors, setCamAssignAvailableMentors] = useState<any[]>([]);
  const [camAssignLoadingMentors, setCamAssignLoadingMentors] = useState(false);
  const [camSelectedCoverMentorId, setCamSelectedCoverMentorId] = useState("");
  const [camAssignSubmitting, setCamAssignSubmitting] = useState(false);

  const openCamAssignModal = (req: any) => {
    setCamAssigningReq(req);
    setCamSelectedCoverMentorId("");
    setCamAssignLoadingMentors(true);
    fetch(`/api/requests/faculty-leave?availableForSlotId=${encodeURIComponent(req.slotId)}&availableForDate=${encodeURIComponent(req.dateStr)}&availableForCollegeId=${encodeURIComponent(activeCollegeId)}&excludeMentorId=${encodeURIComponent(req.requestorId)}`)
      .then(r => r.json())
      .then(data => {
        setCamAssignAvailableMentors(data.mentors || []);
        if (data.mentors && data.mentors.length > 0) {
          setCamSelectedCoverMentorId(data.mentors[0].id);
        }
      })
      .catch(() => setCamAssignAvailableMentors([]))
      .finally(() => setCamAssignLoadingMentors(false));
  };

  const handleCamAssignConfirm = async () => {
    if (!camAssigningReq || !camSelectedCoverMentorId) {
      toast("Please select a faculty member to assign.", "error");
      return;
    }
    setCamAssignSubmitting(true);
    try {
      const res = await fetch("/api/requests/review", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          requestId: camAssigningReq.id,
          action: "cam_reassign",
          targetStaffId: camSelectedCoverMentorId,
          approverName: currentCAM?.name || "Campus Manager",
          actorRole: "Campus Manager"
        })
      });
      const data = await res.json();
      if (data.success) {
        toast("Cover faculty assigned and confirmed successfully!", "success");
        setCamAssigningReq(null);
        // Surgically mark request as approved in state
        // The cam_reassign action ultimately closes/approves the request
      } else {
        toast(data.message || "Failed to assign cover faculty.", "error");
      }
    } catch (err: any) {
      toast("Error: " + err.message, "error");
    } finally {
      setCamAssignSubmitting(false);
    }
  };
  // Load and save state
  useEffect(() => {
    // Allowed Student Profile Edit Classes
    const savedEditClasses = localStorage.getItem("fp_allowed_profile_edit_classes");
    if (savedEditClasses) {
      setAllowedProfileEditClasses(JSON.parse(savedEditClasses));
    }
  }, []);

  useEffect(() => {
    if (academicYears.length > 0 && !academicYears.includes(selectedYear)) {
      setSelectedYear(academicYears[0]);
      setCurrYear(academicYears[0]);
      setEditSubYear(academicYears[0]);
    }
  }, [academicYears, selectedYear]);

  // Additional derived filters and variables

  const activeBatches = useMemo(() => {
    // Derive from STUDENTS first, and deduplicate normalized names
    const fromStudents = collegeStudents.map(s => s.classGroup).filter(Boolean);
    const fromSlots = collegeSlots.map(s => s.classGroup).filter(Boolean);
    const all = [...fromStudents, ...fromSlots];
    
    // Group and deduplicate: if two items match via isCohortMatch, normalize to canonical name
    const unique: string[] = [];
    for (const item of all) {
      const trimmed = (item || "").trim();
      if (!trimmed) continue;
      const canonical = normalizeClassGroup(trimmed) || trimmed;
      const alreadyExists = unique.some(u => isCohortMatch(u, canonical));
      if (!alreadyExists) {
        unique.push(canonical);
      }
    }
    return unique.sort();
  }, [collegeStudents, collegeSlots]);

  const classrooms = useMemo(() => {
    const activeCol = colleges.find(c => c.id === activeCollegeId);
    const colRooms = activeCol?.rooms ? parseRoomsList(activeCol.rooms) : [];
    const slotRooms = collegeSlots.map(s => s.location).filter(Boolean);
    return Array.from(new Set([...colRooms, ...slotRooms])).map(r => r.replace(/[\[\]"]/g, "").trim()).filter(Boolean);
  }, [collegeSlots, colleges, activeCollegeId]);

  const collegeDepts = useMemo(() => {
    if (isGlobalAllCampuses) return departmentsList;
    return departmentsList.filter(d => !d.college_id || d.college_id === activeCollegeId);
  }, [departmentsList, activeCollegeId, isGlobalAllCampuses]);

  const facultyDepts = useMemo(() => {
    const fromCourses = collegeCourses.map(c => c.name?.trim()).filter(Boolean);
    const fromDepartments = (collegeDepts || []).map(d => d.name?.trim()).filter(Boolean);
    const fromStudents = collegeStudents.map(s => s.department?.trim()).filter(Boolean) as string[];
    const fromMentors = collegeMentors.map(m => m.department?.trim()).filter(Boolean) as string[];

    const map = new Map<string, string>();
    fromCourses.forEach(c => {
      const norm = c.toLowerCase().replace(/[^a-z0-9]/g, "");
      if (norm && !map.has(norm)) map.set(norm, c);
    });
    fromDepartments.forEach(d => {
      const norm = d.toLowerCase().replace(/[^a-z0-9]/g, "");
      if (norm && !map.has(norm)) map.set(norm, d);
    });
    fromStudents.forEach(s => {
      const norm = s.toLowerCase().replace(/[^a-z0-9]/g, "");
      if (norm && norm !== "general" && !map.has(norm)) map.set(norm, s);
    });
    fromMentors.forEach(m => {
      const norm = m.toLowerCase().replace(/[^a-z0-9]/g, "");
      if (norm && norm !== "general" && !map.has(norm)) map.set(norm, m);
    });

    if (map.size === 0 && fromMentors.some(m => m.toLowerCase() === "general")) {
      map.set("general", "General");
    }

    return Array.from(map.values()).sort();
  }, [collegeCourses, collegeDepts, collegeStudents, collegeMentors]);

  const isFacultyInDept = useCallback((m: Mentor, targetDept: string): boolean => {
    if (!targetDept || targetDept === "all") return true;
    const fNorm = targetDept.toLowerCase().replace(/[^a-z0-9]/g, "");
    const mDept = (m.department || "").toLowerCase().replace(/[^a-z0-9]/g, "");
    const mGroup = (m.mentor_group || "").toLowerCase().replace(/[^a-z0-9]/g, "");
    const sGroup = (m.subject_group || "").toLowerCase().replace(/[^a-z0-9]/g, "");

    // 1. Direct or partial match on department / mentor_group / subject_group
    if (mDept === fNorm || mDept.includes(fNorm) || fNorm.includes(mDept)) return true;
    if (mGroup === fNorm || mGroup.includes(fNorm) || fNorm.includes(mGroup)) return true;
    if (sGroup === fNorm || sGroup.includes(fNorm) || fNorm.includes(sGroup)) return true;

    // 2. If college has only 1 individual department, any "General" or unassigned mentor belongs to it
    if ((mDept === "general" || !mDept) && facultyDepts.length === 1 && fNorm === facultyDepts[0].toLowerCase().replace(/[^a-z0-9]/g, "")) {
      return true;
    }

    // 3. Match via subjects assigned to mentor
    const mSubjects = (m.subjects || "").toLowerCase();
    const collegeSubList = (collegeSubjects || []).filter(s => {
      const sDept = (s.department || "").toLowerCase().replace(/[^a-z0-9]/g, "");
      return sDept === fNorm || sDept.includes(fNorm);
    });
    if (collegeSubList.some(s => mSubjects.includes(s.name.toLowerCase()))) {
      return true;
    }

    // 4. Match via timetable slots assigned to mentor
    const mentorSlots = collegeSlots.filter(s => s.mentorId === m.id);
    if (mentorSlots.some(s => {
      const sDept = (s.department || "").toLowerCase().replace(/[^a-z0-9]/g, "");
      const sCourse = (s.course || "").toLowerCase().replace(/[^a-z0-9]/g, "");
      const sCG = (s.classGroup || "").toLowerCase().replace(/[^a-z0-9]/g, "");
      return sDept === fNorm || sDept.includes(fNorm) || sCourse.includes(fNorm) || sCG.includes(fNorm);
    })) {
      return true;
    }

    return false;
  }, [facultyDepts, collegeSubjects, collegeSlots]);

  const studentDepts = useMemo(() => {
    return Array.from(new Set(collegeStudents.map(s => s.department?.trim()).filter(Boolean))).sort();
  }, [collegeStudents]);

  // ═══════════════════════════════════════════════════════════════════════════
  // ── ATTENDANCE MONITORING — PRE-COMPUTED MEMOS (component-level, stable)  ──
  // These MUST live here at component level, not inside any IIFE/render block.
  // ═══════════════════════════════════════════════════════════════════════════

  /** O(1) map: `${studentId}_${dateStr}` → attendance records[] */
  const attMonitoringMap = useMemo(() => {
    const map = new Map<string, any[]>();
    (studentAttendance || []).forEach(a => {
      if (!a.studentId || !a.dateStr) return;
      const k = `${a.studentId}_${a.dateStr}`;
      const existing = map.get(k);
      if (existing) existing.push(a);
      else map.set(k, [a]);
    });
    return map;
  }, [studentAttendance]);

  /** O(1) Daily Config Map lookup by dateStr */
  const attMonitoringDailyConfigMap = useMemo(() => {
    const map = new Map<string, any>();
    (dailyConfigsList || []).forEach((c: any) => {
      if (c?.dateStr) map.set(c.dateStr, c);
    });
    return map;
  }, [dailyConfigsList]);

  /** O(1) Holiday map lookup combining static holidays AND dailyConfigsList where day_type === 'holiday' */
  const attMonitoringHolidayMap = useMemo(() => {
    const map = new Map<string, any>();
    (holidays || []).forEach((h: any) => {
      const d = h?.date || h?.dateStr;
      if (d) map.set(d, { isHoliday: true, name: h.name || h.description || "College Holiday", notes: h.notes || h.name || "College Holiday" });
    });
    (dailyConfigsList || []).forEach((c: any) => {
      if (c?.dateStr && (c.day_type === "holiday" || (c.day_order && c.day_order.toLowerCase() === "none" && c.day_type === "holiday"))) {
        const existing = map.get(c.dateStr);
        map.set(c.dateStr, {
          isHoliday: true,
          name: c.notes || existing?.name || "College Holiday",
          notes: c.notes || existing?.notes || "College Holiday",
          ...c
        });
      }
    });
    return map;
  }, [holidays, dailyConfigsList]);

  /** Sorted working dates in the selected date range — unified source of truth */
  const attMonitoringWorkingDates = useMemo(() => {
    return getSemesterWorkingDates(attendanceStartDate, attendanceEndDate);
  }, [attendanceStartDate, attendanceEndDate, holidays, dailyConfigsList, studentAttendance]);

  /** Set of exam dates (O(1) lookup to replace per-cell isExamDate() scan) */
  const attMonitoringExamDateSet = useMemo(() => {
    const s = new Set<string>();
    attMonitoringWorkingDates.forEach(d => {
      if (isExamDate(d, dailyConfigsList, studentAttendance)) s.add(d);
    });
    return s;
  }, [attMonitoringWorkingDates, dailyConfigsList, studentAttendance]);

  /** Pre-computed effective day name for each date, respecting Day Order (Day 1->Mon, Day 2->Tue, etc.) */
  const attMonitoringDayNameMap = useMemo(() => {
    const m: Record<string, string> = {};
    attMonitoringWorkingDates.forEach(d => {
      const cfg = attMonitoringDailyConfigMap.get(d);
      const defaultWeekday = new Date(d + "T00:00:00").toLocaleDateString("en-US", { weekday: "long" });
      m[d] = mapDayOrderToDayName(cfg?.day_order, defaultWeekday);
    });
    return m;
  }, [attMonitoringWorkingDates, attMonitoringDailyConfigMap]);

  /** Slot lookup map: `${dayName}__${classGroupLower}` → Slot[] */
  const attMonitoringSlotMap = useMemo(() => {
    const map = new Map<string, any[]>();
    collegeSlots.forEach(s => {
      const rawKey = `${s.day}__${(s.classGroup || "").toLowerCase()}`;
      const normKey = `${s.day}__${(s.classGroup || "").replace(/\s*\(\d{4}[–\-]\d{4}\)/g, "").replace(/\s*-\s*Batch\s*\d{4}[–\-]\d{4}/gi, "").trim().toLowerCase()}`;

      const existing = map.get(rawKey);
      if (existing) existing.push(s);
      else map.set(rawKey, [s]);

      if (normKey !== rawKey) {
        const normArr = map.get(normKey);
        if (normArr) normArr.push(s);
        else map.set(normKey, [s]);
      }
    });
    return map;
  }, [collegeSlots]);

  /** Filtered students for the monitoring tab */
  const attMonitoringFiltered = useMemo(() => {
    const q = (deferredStudentSearch || "").trim().toLowerCase();
    return collegeStudents.filter(s => {
      const matchesSearch = !q || s.name.toLowerCase().includes(q) ||
                            (s.roll_number && s.roll_number.toLowerCase().includes(q)) ||
                            s.id.toLowerCase().includes(q);
      const matchesDept  = studentDeptFilter  === "all" || s.department === studentDeptFilter || isDeptSubjectMatch(s.department, studentDeptFilter);
      const matchesBatch = studentBatchFilter === "all" || s.classGroup === studentBatchFilter || isCohortMatch(s.classGroup, studentBatchFilter);
      return matchesSearch && matchesDept && matchesBatch;
    });
  }, [collegeStudents, deferredStudentSearch, studentDeptFilter, studentBatchFilter]);

  /** Per-student compliance stats (powers both infographics AND the table %) */
  const attMonitoringStudentStats = useMemo(() => {
    return attMonitoringFiltered.map(st => {
      let presentDays = 0, absentDays = 0, totalMarkedDays = 0;
      attMonitoringWorkingDates.forEach(dStr => {
        const holidayObj = attMonitoringHolidayMap.get(dStr);
        const cfg = attMonitoringDailyConfigMap.get(dStr);
        const isSunday = new Date(dStr + "T00:00:00").getDay() === 0;
        const isExplicitWorkingSunday = isSunday && cfg?.day_type === "working" && cfg?.day_order && cfg.day_order !== "None";
        if ((!isExplicitWorkingSunday && isSunday) || holidayObj || cfg?.day_type === "holiday") return; // Holidays & Sundays are excluded from compliance calculations

        const recs = attMonitoringMap.get(`${st.id}_${dStr}`);
        if (!recs || recs.length === 0) return;
        totalMarkedDays++;
        const isExam = attMonitoringExamDateSet.has(dStr);
        const ev     = evaluateDailyStudentAttendance(recs, 0, isExam, false, cfg?.notes || "");
        presentDays += ev.presentDays;
        absentDays  += ev.absentDays;
      });
      const pct = totalMarkedDays > 0 ? Math.round((presentDays / totalMarkedDays) * 100) : -1;
      return {
        id: st.id, name: st.name,
        cg: st.classGroup || st.department || "General",
        pct, hasData: totalMarkedDays > 0,
        presentDays, absentDays, totalMarkedDays,
      };
    });
  }, [attMonitoringFiltered, attMonitoringWorkingDates, attMonitoringMap, attMonitoringExamDateSet, attMonitoringHolidayMap, attMonitoringDailyConfigMap]);

  /** O(1) Student Stats Map lookup */
  const attMonitoringStudentStatsMap = useMemo(() => {
    return new Map(attMonitoringStudentStats.map(s => [s.id, s]));
  }, [attMonitoringStudentStats]);

  /** Infographic aggregates derived from studentStats */
  const attMonitoringChartData = useMemo(() => {
    const onTrack  = attMonitoringStudentStats.filter(s => s.pct >= 75).length;
    const atRisk   = attMonitoringStudentStats.filter(s => s.pct >= 65 && s.pct < 75).length;
    const critical = attMonitoringStudentStats.filter(s => s.pct >= 0 && s.pct < 65).length;
    const noData   = attMonitoringStudentStats.filter(s => !s.hasData).length;
    const cgMap: Record<string, { sum: number; count: number }> = {};
    attMonitoringStudentStats.filter(s => s.hasData).forEach(s => {
      if (!cgMap[s.cg]) cgMap[s.cg] = { sum: 0, count: 0 };
      cgMap[s.cg].sum   += s.pct;
      cgMap[s.cg].count += 1;
    });
    const cgChartData = Object.entries(cgMap)
      .map(([name, v]) => ({ name: name.length > 16 ? name.slice(0, 16) + "…" : name, pct: Math.round(v.sum / v.count) }))
      .sort((a, b) => b.pct - a.pct).slice(0, 8);
    const totalPresent    = attMonitoringStudentStats.reduce((a, s) => a + s.presentDays, 0);
    const totalPossible   = attMonitoringStudentStats.reduce((a, s) => a + s.totalMarkedDays, 0);
    const overallAvgPct   = totalPossible > 0 ? Math.round((totalPresent / totalPossible) * 100) : 0;
    return { onTrack, atRisk, critical, noData, cgChartData, overallAvgPct };
  }, [attMonitoringStudentStats]);

  /** Memoized Donut data — stable array reference ensures React.memo(AttMonitoringCharts) works */
  const attMonitoringDonutData = useMemo(() => {
    const { onTrack, atRisk, critical, noData } = attMonitoringChartData;
    return [
      { name: "On Track (≥75%)",  value: onTrack,  color: "#10b981" },
      { name: "At Risk (65–74%)", value: atRisk,   color: "#f59e0b" },
      { name: "Critical (<65%)",  value: critical, color: "#f43f5e" },
      { name: "No Data",          value: noData,   color: "#cbd5e1" },
    ].filter(d => d.value > 0);
  }, [attMonitoringChartData]);

  // ═══════════════════════════════════════════════════════════════════════════

  const depts = useMemo(() => {
    return Array.from(new Set([...facultyDepts, ...studentDepts])).sort();
  }, [facultyDepts, studentDepts]);

  const activeHandovers = useMemo(() => {
    return requests.filter(r =>
      r.status === "pending" &&
      mentors.find(m => m.id === r.requestorId)?.college_id === activeCollegeId
    );
  }, [requests, mentors, activeCollegeId]);



  // Helper to find matching batch
  const findMatchingBatch = (course: string, sem: string, targetShift?: "shift_1" | "shift_2" | "general") => {
    if (!course) return activeBatches[0] || "";
    const sh = targetShift || viewerShift;

    // 1. Try to find a batch in activeBatches matching course, sem, and specifically the target shift
    const matchWithShift = activeBatches.find(cg => {
      const slot = collegeSlots.find(s => s.classGroup === cg);
      const c = slot?.department || getCourseFromClassGroup(cg);
      if (c !== course) return false;
      
      const s = slot?.semester || getSemesterFromClassGroup(cg);
      if (sem && s !== sem) return false;

      const cgLower = cg.toLowerCase();
      const hasShiftSlots = collegeSlots.some(sl => sl.classGroup === cg && (sl.shift || "general").toLowerCase() === sh.toLowerCase());
      if (hasShiftSlots) return true;

      if (sh === "shift_1") return cgLower.includes("shift 1") || cgLower.includes("shift_1") || cgLower.includes("shift1") || cgLower.includes("s1");
      if (sh === "shift_2") return cgLower.includes("shift 2") || cgLower.includes("shift_2") || cgLower.includes("shift2") || cgLower.includes("s2");
      if (sh === "general") return cgLower.includes("general") || (!cgLower.includes("shift 1") && !cgLower.includes("shift 2") && !cgLower.includes("shift_1") && !cgLower.includes("shift_2") && !cgLower.includes("shift1") && !cgLower.includes("shift2"));
      return false;
    });
    if (matchWithShift) return matchWithShift;

    // 2. Fallback to any batch matching course and sem
    const matchCourseSem = activeBatches.find(cg => {
      const slot = collegeSlots.find(s => s.classGroup === cg);
      const c = slot?.department || getCourseFromClassGroup(cg);
      if (c !== course) return false;
      const s = slot?.semester || getSemesterFromClassGroup(cg);
      if (sem && s !== sem) return false;
      return true;
    });
    if (matchCourseSem) return matchCourseSem;

    // 3. Fallback to any batch matching course
    const matchCourseOnly = activeBatches.find(cg => {
      const slot = collegeSlots.find(s => s.classGroup === cg);
      const c = slot?.department || getCourseFromClassGroup(cg);
      return c === course;
    });
    return matchCourseOnly || activeBatches[0] || "";
  };

  // Re-sync divided dropdown states when activeBatches or activeCollegeId changes
  useEffect(() => {
    if (activeBatches.length > 0) {
      // Get unique courses
      const courses = Array.from(new Set(activeBatches.map(cg => {
        const slot = collegeSlots.find(s => s.classGroup === cg);
        return slot?.department || getCourseFromClassGroup(cg);
      }).filter(Boolean)));
      
      let defaultCourse = selectedCohortCourse;
      if (!defaultCourse || !courses.includes(defaultCourse)) {
        defaultCourse = courses[0] || "";
      }
      setSelectedCohortCourse(defaultCourse);
      
      // Get sems for this defaultCourse
      const semsForCourse = activeBatches
        .filter(cg => {
          const slot = collegeSlots.find(s => s.classGroup === cg);
          const c = slot?.department || getCourseFromClassGroup(cg);
          return c === defaultCourse;
        })
        .map(cg => {
          const slot = collegeSlots.find(s => s.classGroup === cg);
          return slot?.semester || getSemesterFromClassGroup(cg);
        });
      
      let defaultSem = selectedCohortSem;
      if (!defaultSem || !semsForCourse.includes(defaultSem)) {
        defaultSem = semsForCourse[0] || "";
      }
      setSelectedCohortSem(defaultSem);
      
      const matched = findMatchingBatch(defaultCourse, defaultSem, viewerShift);
      setViewerClassGroup(matched);
    } else {
      setSelectedCohortCourse("");
      setSelectedCohortSem("");
      setViewerClassGroup("");
    }
    setInitializedCollegeId("");
  }, [activeBatches, activeCollegeId, collegeSlots]);

  // Handle manual selection changes
  const handleCohortCourseChange = (course: string) => {
    setSelectedCohortCourse(course);
    // Find sems for this course
    const sems = activeBatches
      .filter(cg => {
        const slot = collegeSlots.find(s => s.classGroup === cg);
        const c = slot?.department || getCourseFromClassGroup(cg);
        return c === course;
      })
      .map(cg => {
        const slot = collegeSlots.find(s => s.classGroup === cg);
        return slot?.semester || getSemesterFromClassGroup(cg);
      });
    const firstSem = sems[0] || "";
    setSelectedCohortSem(firstSem);
    
    const matched = findMatchingBatch(course, firstSem, viewerShift);
    setViewerClassGroup(matched);
  };

